def test_a_value_that_fails_its_type_is_refused_and_the_file_is_untouched(
    qapp: object, ps: _Ps, tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    view = _tuned_view(ps, tmp_path)
    path = tmp_path / TRANSMOG_CONF
    before = path.read_text(encoding="utf-8")
    card = view.tuning_panel.card("mod-transmog")
    key = "Transmogrification.Enable"
    # The shipped manifest types this key `bool`, and a switch cannot produce a
    # value that fails its own check. The refusal is asked for by handing
    # `tuning.check()` a declaration the switch's `0` cannot satisfy -- the spec
    # is read at SAVE time, and the control was drawn before it.
    monkeypatch.setattr(
        view,
        "_tuning_spec",
        lambda family, module_id, file: {key: ConfKey(key=key, type="int", min=5, max=9)},
    )
    card.editors[key].control.setChecked(False)
    failures: list[str] = []
    view.action_failed.connect(failures.append)
    assert card.save_button is not None
    card.save_button.click()
    assert path.read_text(encoding="utf-8") == before
    assert tuning.backups_of(path) == ()
    assert key in view.tuning_report.toPlainText()
    assert failures and key in failures[0]


def test_revert_puts_the_conf_back_from_the_backup(qapp: object, ps: _Ps, tmp_path: Path) -> None:
    view = _tuned_view(ps, tmp_path)
    path = tmp_path / TRANSMOG_CONF
    before = path.read_text(encoding="utf-8")
    card = view.tuning_panel.card("mod-transmog")
    card.editors["Transmogrification.Enable"].control.setChecked(False)
    assert card.save_button is not None and card.revert_button is not None
    card.save_button.click()
    assert path.read_text(encoding="utf-8") != before
    view.tuning_panel.card("mod-transmog").revert_button.click()
    assert path.read_text(encoding="utf-8") == before


@pytest.mark.parametrize("typed", ["１２", "١٢", "1_000", " 5", "+5", "0x10", "4294967296", "-1"])
def test_a_number_the_server_would_read_differently_is_refused_at_save(
    qapp: object, ps: _Ps, tmp_path: Path, typed: str
) -> None:
    """Through the card's own Save: `int()` reads each of these, the server does not.

    `AuctionHouseBot.ItemsPerCycle` is an `int` with no bounds, so it is a text
    box and nothing but the spelling rule stands between the text and the conf.
    """
    from PySide6.QtWidgets import QLineEdit

    from tests.support_player_text import command_faults, text_faults

    conf = "env/dist/etc/modules/mod_ahbot.conf"
    _deploy(tmp_path, conf, "[worldserver]\nAuctionHouseBot.ItemsPerCycle = 200\n")
    view = _installed_view(ps, tmp_path, module=frozenset({"mod-ah-bot-plus"}))
    before = (tmp_path / conf).read_bytes()
    card = view.tuning_panel.card("mod-ah-bot-plus")
    box = card.editors["AuctionHouseBot.ItemsPerCycle"].control
    assert isinstance(box, QLineEdit)
    box.setText(typed)
    failures: list[str] = []
    view.action_failed.connect(failures.append)
    assert card.save_button is not None
    card.save_button.click()
    assert (tmp_path / conf).read_bytes() == before
    assert tuning.backups_of(tmp_path / conf) == ()
    said = view.tuning_report.toPlainText()
    assert "AuctionHouseBot.ItemsPerCycle" in said
    assert failures and command_faults(failures[0]) == [], failures
    assert command_faults(said) == [] and text_faults(said) == [], said


@pytest.mark.parametrize("answer", [True, False])
def test_the_raw_editor_warns_about_a_bad_int_key_and_the_player_decides(
    qapp: object, ps: _Ps, tmp_path: Path, monkeypatch: pytest.MonkeyPatch, answer: bool
) -> None:
    """T371: `ItemsPerCycle = +5` typed in the raw box is the same refusal the card gives.

    Non-blocking, as the editor's lint always is: one confirm that names the key,
    and Yes still saves. A good value and another key's free text ask nothing.
    """
    from yulon.ui import controller_view as controller_view_module

    conf = "env/dist/etc/modules/mod_ahbot.conf"
    _deploy(tmp_path, conf, "[worldserver]\nAuctionHouseBot.ItemsPerCycle = 200\n")
    view = _installed_view(ps, tmp_path, module=frozenset({"mod-ah-bot-plus"}))
    view.open_tuning_file(conf)
    asked: list[str] = []

    def question(_parent: object, _title: str, said: str, *_a: object, **_k: object) -> int:
        asked.append(said)
        buttons = controller_view_module.QMessageBox.StandardButton
        return int(buttons.Yes if answer else buttons.No)

    monkeypatch.setattr(controller_view_module.QMessageBox, "question", question)
    bad = "[worldserver]\nAuctionHouseBot.ItemsPerCycle = +5\n"
    view.save_tuning_file(bad)
    assert len(asked) == 1 and "AuctionHouseBot.ItemsPerCycle" in asked[0], asked
    kept = "[worldserver]\nAuctionHouseBot.ItemsPerCycle = 200\n"
    assert (tmp_path / conf).read_text(encoding="utf-8") == (bad if answer else kept)
    asked.clear()
    view.save_tuning_file("[worldserver]\nAuctionHouseBot.ItemsPerCycle = 3000000000\n")
    assert asked == []


