    jobs = _Deferred()
    services = replace(
        _services(ps, tmp_path, []), client_dir=original, play_client_dir=play, uninstall=uninstall
    )
    services.set_play_client_dir = _FakeClientDir()
    view = ControllerView(WOTLK, services, status_poll_ms=0, job_runner=jobs)
